const articles = $input.all();

const latest = articles
  .filter(item =>
    item.json.title &&
    item.json.link &&
    item.json.isoDate
  )
  .sort((a, b) =>
    new Date(b.json.isoDate) - new Date(a.json.isoDate)
  )
  .slice(0, 5);

return latest.map(item => ({
  json: {
    title: item.json.title,
    link: item.json.link,
    published: item.json.isoDate,
    description: item.json.contentSnippet || ""
  }
}));

const raw = ($input.first().json.content?.parts ?? [])
  .filter(part => !part.thought && typeof part.text === 'string')
  .map(part => part.text)
  .join('');

if (!raw.trim()) {
  throw new Error("Gemini response is empty.");
}

const cleaned = raw.trim()
  .replace(/^```(?:json)?\s*/i, "")
  .replace(/\s*```$/i, "");

const data = JSON.parse(cleaned);

if (!Array.isArray(data.articles) || data.articles.length !== 5) {
  throw new Error("Expected exactly 5 articles.");
}

// Escape special characters for Telegram HTML.
function escapeHtml(value) {
  return String(value ?? "")
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;");
}

const date = new Date().toLocaleDateString("en-US", {
  timeZone: "Europe/Istanbul",
  year: "numeric",
  month: "long",
  day: "numeric"
});

const lines = [
  "📰 <b>DAILY AI NEWS DIGEST</b>",
  `📅 ${date}`,
  "",
  "━━━━━━━━━━━━",
  ""
];

data.articles.forEach((article, index) => {
  const title = escapeHtml(article.title);
  const summary = escapeHtml(article.summary);
  const url = escapeHtml(article.url);

  lines.push(
    `<b>${index + 1}. ${title}</b>`,
    "",
    summary,
    "",
    `<a href="${url}">🔗 Read Article</a>`,
    "",
    "━━━━━━━━━━━━",
    ""
  );
});

lines.push("🤖 <i>Powered by Synflowry AI</i>");

return [{
  json: {
    message: lines.join("\n"),
    article_count: data.articles.length
  }
}];
